#define main historical_main
#include "../divergence-cuda/divergence.cu"
#undef main
#include <vector>
#include <cmath>
#define CK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
struct Fixture{double v[4][4][2];element<4,double>e;derivative<4,double>d;double gold[16];double determinant;};
Fixture fixture(int kind){Fixture f;double nodes[4]={-1.,-1./sqrt(5.),1./sqrt(5.),1.},weights[4]={1,1,1,1};for(int i=0;i<4;i++){for(int j=0;j<4;j++)if(i!=j)weights[i]*=nodes[i]-nodes[j];weights[i]=1./weights[i];}for(int i=0;i<4;i++){double s=0;for(int j=0;j<4;j++)if(i!=j){double value=weights[j]/(weights[i]*(nodes[i]-nodes[j]));f.d.Dvv[i][j]=value;s+=value;}f.d.Dvv[i][i]=-s;}double a=kind?2.:1.,b=kind?.25:0.,c=kind?.5:0.,d=kind?1.5:1.;f.determinant=a*d-b*c;for(int j=0;j<4;j++)for(int i=0;i<4;i++){double x=a*nodes[i]+b*nodes[j],y=c*nodes[i]+d*nodes[j];f.v[j][i][0]=x*x+2.*y;f.v[j][i][1]=x*y+y*y;f.e.metdet[j][i]=f.determinant;f.e.rmetdet[j][i]=1./f.determinant;f.e.Dinv[j][i][0][0]=d/f.determinant;f.e.Dinv[j][i][0][1]=-b/f.determinant;f.e.Dinv[j][i][1][0]=-c/f.determinant;f.e.Dinv[j][i][1][1]=a/f.determinant;f.gold[4*j+i]=(3.*x+2.*y)*1.5683814303638645e-7;}return f;}
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):10;if(repeat<1)return 2;std::vector<Fixture>fs={fixture(0),fixture(1)};std::vector<double>prefix;for(auto&f:fs){prefix.insert(prefix.end(),&f.v[0][0][0],&f.v[0][0][0]+32);prefix.insert(prefix.end(),&f.e.metdet[0][0],&f.e.metdet[0][0]+16);prefix.insert(prefix.end(),&f.e.Dinv[0][0][0][0],&f.e.Dinv[0][0][0][0]+64);prefix.insert(prefix.end(),&f.e.rmetdet[0][0],&f.e.rmetdet[0][0]+16);prefix.insert(prefix.end(),&f.d.Dvv[0][0],&f.d.Dvv[0][0]+16);double cpu[4][4],warm[4][4];divergence_sphere_cpu<4,double>(f.v,f.d,f.e,cpu);for(int q=0;q<16;q++)if(fabs((&cpu[0][0])[q]-f.gold[q])>1e-20+1e-12*fabs(f.gold[q])){fprintf(stderr,"OriginalCPU fails manufacturedoracle\n");return 3;}divergence_sphere_gpu<4,double>(f.v,f.d,f.e,warm);}CK(cudaDeviceSynchronize());bool allok=true;
for(int trial=1;trial<=5;trial++){double seconds=0,ma=0,mr=0;std::vector<double>out=prefix;bool ok=true;for(auto&f:fs){std::vector<double>got(repeat*16);CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int rep=0;rep<repeat;rep++)divergence_sphere_gpu<4,double>(f.v,f.d,f.e,reinterpret_cast<double(*)[4]>(got.data()+rep*16));CK(cudaDeviceSynchronize());seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;for(int rep=0;rep<repeat;rep++)for(int q=0;q<16;q++){double x=got[rep*16+q],e=fabs(x-f.gold[q]);ma=fmax(ma,e);mr=fmax(mr,e/fmax(fabs(f.gold[q]),1e-300));ok&=std::isfinite(x)&&e<=1e-20+1e-12*fabs(f.gold[q]);}out.insert(out.end(),got.begin(),got.end());}allok&=ok;char file[80];sprintf(file,"divergence_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(out.data(),sizeof(double),out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"timing_region\":\"sum_two_NP4_full_native_workflows_CPU_contravariant_allocation_H2D_kernel_D2H_free\",\"jit_excluded\":true,\"internal_repeats\":%d,\"input_prefix_values\":288,\"divergence_output_values\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",out.size(),ma,mr,repeat,32*repeat,file,out.size());}puts(allok?"PASS":"FAIL");return allok?0:1;}
